    'help' => [
        'page_title' => 'Service Desk - Οδηγός εργασιών',
        'guide' => 'Οδηγός',
        'nav_overview' => 'Επισκόπηση',
        'nav_board' => 'Ο πίνακας',
        'nav_list' => 'Προβολή λίστας',
        'nav_calendar' => 'Προβολή ημερολογίου',
        'nav_timeline' => 'Προβολή χρονολογίου',
        'nav_table' => 'Προβολή πίνακα',
        'nav_panel' => 'Το πάνελ εργασίας',
        'nav_tags' => 'Ετικέτες',
        'nav_evidence' => 'Ιστορικό και τεκμηρίωση',
        'evidence_heading' => 'Ιστορικό και τεκμηρίωση',
        'evidence_intro' => 'Κάθε εργασία διατηρεί ιστορικό και κάθε επαναλαμβανόμενη εργασία έχει αναφορά τεκμηρίωσης: το αρχείο που ζητά ένας ελεγκτής όταν λέει &ldquo;δείξτε μου ότι αυτός ο έλεγχος έγινε κάθε μήνα φέτος&rdquo;.',
        'evidence_history_heading' => 'Το Ιστορικό μιας εργασίας',
        'case_report_heading' => 'Αναφορά υπόθεσης για μία εργασία',
        'case_report_body' => 'Το κουμπί <strong>έγγραφο</strong> στο πάνω μέρος του παραθύρου της εργασίας ανοίγει την εργασία και τις υποεργασίες της ως μία εκτυπώσιμη αναφορά - στοιχεία, περιγραφή, αποτελέσματα λιστών ελέγχου, φόρμες, διαδικασίες που ακολουθήθηκαν, ενέργειες παρακολούθησης, σχόλια, ιστορικό και τα συνημμένα αρχεία. Επιλέξτε <strong>Εκτύπωση</strong> και μετά <em>Αποθήκευση ως PDF</em>. Για μια εργασία που ανήκει σε αίτημα, συνήθως είναι καλύτερο να εκδώσετε την αναφορά από την <strong>Εξαγωγή</strong> του αιτήματος, που περιλαμβάνει και τη συνομιλία. Η εκτύπωση καταγράφεται στο ιστορικό της εργασίας.',
        'evidence_history_body' => 'Η καρτέλα <strong>Ιστορικό</strong> στο παράθυρο της εργασίας απαριθμεί ό,τι συνέβη στην εργασία, με τα πιο πρόσφατα πρώτα: ποιος τη δημιούργησε (άτομο ή <em>η επανάληψη</em>), κάθε αλλαγή κατάστασης, <strong>ποιος την ολοκλήρωσε</strong> και ποια ήταν η προθεσμία εκείνη τη στιγμή, το ξανάνοιγμα, τις αλλαγές προθεσμίας, ημερομηνίας έναρξης και υπευθύνου, μια παράλειψη και τον λόγο της, τις λίστες ελέγχου που προσαρτήθηκαν και αφαιρέθηκαν, και κάθε επιλογή, αποεπιλογή, τιμή και αποτέλεσμα στα βήματα της λίστας ελέγχου. Οι αλλαγές που έγιναν μετά την ολοκλήρωση της εργασίας το αναφέρουν. Τίποτα σε αυτό δεν μπορεί να επεξεργαστεί ή να διαγραφεί και παραμένει καταγεγραμμένο ακόμη και αν η εργασία διαγραφεί.',
        'evidence_history_note' => 'Το ιστορικό ξεκινά από την ημέρα που προστέθηκε αυτό το χαρακτηριστικό στο FreeITSM σας. Ό,τι προηγείται - για παράδειγμα ποιος ολοκλήρωσε μια παλαιότερη εργασία - δεν καταγράφηκε ποτέ και η αναφορά γράφει <em>δεν καταγράφηκε</em> αντί να μαντέψει.',
        'evidence_report_heading' => 'Η αναφορά τεκμηρίωσης',
        'evidence_report_body' => 'Ανοίξτε την από μια επαναλαμβανόμενη εργασία (<strong>Επαναλήψεις &rarr; Ιστορικό εκτελέσεων</strong>) ή από το <strong>Εργασίες &rarr; Τεκμηρίωση</strong>, που απαριθμεί κάθε επαναλαμβανόμενη εργασία - και τις σταματημένες και εκείνες των οποίων όλες οι εργασίες έχουν διαγραφεί. Επιλέξτε μια περίοδο <em>προγραμματισμένων</em> ημερομηνιών. Κάθε εκτέλεση που έπρεπε να είχε γίνει παίρνει μία γραμμή με το αποτέλεσμά της, ποιος την ολοκλήρωσε, τα αποτελέσματα της λίστας ελέγχου και τυχόν εξαιρέσεις:',
        'evidence_outcome_on_time' => '<strong>Εγκαίρως</strong> - ολοκληρώθηκε έως την αρχική προθεσμία της (την ημερομηνία για την οποία την όρισε η επανάληψη) και έως οποιαδήποτε ημερομηνία στην οποία μεταφέρθηκε.',
        'evidence_outcome_rescheduled' => '<strong>Εγκαίρως μετά από αναπρογραμματισμό</strong> - ολοκληρώθηκε μετά την αρχική προθεσμία της, αλλά έως την ημερομηνία στην οποία είχε μεταφερθεί εκείνη τη στιγμή. Προθεσμία την 1η, μεταφορά στις 8, ολοκλήρωση στις 7 είναι αυτή η περίπτωση - ποτέ απλά Εγκαίρως.',
        'evidence_outcome_late' => '<strong>Με καθυστέρηση</strong> - ολοκληρώθηκε μετά την προθεσμία που ίσχυε εκείνη τη στιγμή.',
        'evidence_outcome_open' => '<strong>Ανοιχτή</strong> και <strong>Εκπρόθεσμη</strong> - δεν έχει ολοκληρωθεί ακόμη, πριν ή μετά την προθεσμία της.',
        'evidence_outcome_skipped' => '<strong>Παραλείφθηκε</strong> - έκλεισε σκόπιμα, με τον λόγο που δόθηκε.',
        'evidence_outcome_missing' => '<strong>Λείπει</strong> - έπρεπε να υπάρχει και δεν υπάρχει. Σε σταθερό πρόγραμμα, μια ημερομηνία που παρήγαγε ο κανόνας χωρίς να υπάρχει εκτέλεση. Μετά την ολοκλήρωση, ποτέ πριν ολοκληρωθεί η προηγούμενη - αλλά όταν μια ολοκλήρωση ή μια παράλειψη έκανε την επόμενη απαιτητή, μια επόμενη που δεν εμφανίστηκε ποτέ θεωρείται ότι λείπει.',
        'evidence_outcome_removed' => '<strong>Καταργήθηκε</strong> - δημιουργήθηκε και στη συνέχεια διαγράφηκε. Τα αποτελέσματα της λίστας ελέγχου, οι εξαιρέσεις και το ιστορικό της διατηρούνται και εμφανίζονται.',
        'evidence_flags' => 'Δίπλα στο αποτέλεσμα εμφανίζονται σημάνσεις: <strong>Αναπρογραμματίστηκε</strong> (η προθεσμία μεταφέρθηκε πριν από την ολοκλήρωση), <strong>Η προθεσμία άλλαξε μετά την ολοκλήρωση</strong> (δεν αλλάζει ποτέ το αποτέλεσμα), <strong>Δημιουργήθηκε αργά</strong> (ο προγραμματιστής την δημιούργησε αφού η εργασία έπρεπε ήδη να έχει ξεκινήσει) και <strong>Άλλαξε μετά την ολοκλήρωση</strong> (ένα βήμα της λίστας ελέγχου άλλαξε αφού είχε ολοκληρωθεί). Οι ώρες εμφανίζονται στη ζώνη ώρας της εγκατάστασης και η προθεσμία είναι ημερολογιακή ημέρα σε αυτήν.',
        'evidence_why' => 'Για μια εκτέλεση που λείπει ή καθυστέρησε, η αναφορά προσθέτει ό,τι δείχνει το ιστορικό εκτελέσεων της εργασίας επαναλήψεων για εκείνη την ώρα (δείτε Αναφορές &rarr; Αρχεία καταγραφής συστήματος &rarr; Εργασίες παρασκηνίου): <em>καμία καταγεγραμμένη εκτέλεση</em>, <em>η εργασία απέτυχε</em> με το μήνυμά της, ή <em>δημιουργήθηκε από εκτέλεση καλύψεως</em>. Δεν λέει ποτέ ότι η εργασία δεν εκτελέστηκε - μόνο ό,τι καταγράφηκε - και γράφει <em>δεν είναι διαθέσιμο</em> για ώρα πριν από την τήρηση ιστορικού εκτελέσεων. Η προβολή ή η εξαγωγή της αναφοράς δεν δημιουργεί ποτέ εργασία.',
        'evidence_skip_heading' => 'Παράλειψη μιας εκτέλεσης',
        'evidence_skip_body' => 'Όταν μια εκτέλεση μιας επανάληψης δεν πρέπει να γίνει - ο διακομιστής που ελέγχει αντικαθίστατο, ας πούμε - χρησιμοποιήστε <strong>Επαναλήψεις &rarr; Παράλειψη</strong> και δώστε τον λόγο. Κλείνει ως <em>παραλείφθηκε</em>, όχι ως ολοκληρωμένη, στην κατάσταση που έχει επιλεγεί στις Ρυθμίσεις &rarr; Τεκμηρίωση, και η αναφορά την εμφανίζει με τον λόγο. Μια επανάληψη που έχει οριστεί να επαναλαμβάνεται μετά την ολοκλήρωση δημιουργεί την επόμενη εκτέλεσή της, όπως θα έκανε η ολοκλήρωσή της.',
        'evidence_results_heading' => 'Επιτυχία, Αποτυχία και Δεν ισχύει',
        'evidence_results_body' => 'Ένα βήμα λίστας ελέγχου μπορεί να ζητά <strong>αποτέλεσμα</strong> αντί για επιλογή: στην ενότητα Λίστες ελέγχου, ενεργοποιήστε το <strong>Ζητείται αποτέλεσμα</strong> στο βήμα. Σε μια εργασία εμφανίζει τότε <strong>Επιτυχία</strong>, <strong>Αποτυχία</strong> και <strong>Δεν ισχύει</strong>, και η Αποτυχία ρωτά τι πήγε στραβά πριν αποθηκευτεί. Η εργασία μπορεί να ολοκληρωθεί και με αποτυχημένο βήμα - η αναφορά το εμφανίζει ως <strong>εξαίρεση</strong>, ώστε μια ολοκληρωμένη εργασία να μην κρύβει ποτέ έναν έλεγχο που δεν πέτυχε. Τα βήματα χωρίς αυτό διατηρούν την επιλογή τους και τα αιτήματα χρησιμοποιούν πάντα την επιλογή. Η αποθήκευση ενός προτύπου λίστας ελέγχου διατηρεί την προηγούμενη έκδοση και κάθε εργασία καταγράφει την έκδοση που της δόθηκε.',
        'evidence_export_heading' => 'Εκτύπωση και εξαγωγή',
        'evidence_export_body' => 'Η <strong>Εκτύπωση</strong> ανοίγει την αναφορά έτοιμη για <em>Εκτύπωση &rarr; Αποθήκευση ως PDF</em>. Τέσσερα αρχεία CSV - εκτελέσεις, αποτελέσματα λίστας ελέγχου, συνημμένα και σχόλια, και απαντήσεις φορμών - μοιράζονται τα αναγνωριστικά εργασιών, ώστε να συνδέονται σε ένα υπολογιστικό φύλλο. Κάθε εκτύπωση και εξαγωγή καταγράφεται στην αναφορά, με το ποιος και πότε.',
        'evidence_auditor_heading' => 'Ρόλος ελεγκτή',
        'evidence_auditor_body' => 'Δώστε σε κάποιον πρόσβαση <strong>Μόνο ανάγνωση</strong> στις Εργασίες (Σύστημα &rarr; Τεχνικοί ή Ομάδες &rarr; Πρόσβαση σε ενότητες) και, αν οι Ρυθμίσεις &rarr; Τεκμηρίωση περιορίζουν την αναφορά, έναν ρόλο που περιέχει το <strong>Εκτέλεση της αναφοράς τεκμηρίωσης</strong>. Μπορεί να ανοίξει κάθε εργασία που επιτρέπουν οι εταιρείες του, να διαβάσει το ιστορικό της και να εκτυπώσει ή να εξαγάγει την τεκμηρίωση, αλλά δεν μπορεί να δημιουργήσει, να αλλάξει, να ολοκληρώσει, να παραλείψει ή να διαγράψει τίποτα. Για να μπορεί να διαβάζει τις απαντήσεις των φορμών σε αυτές τις εργασίες χωρίς να του δώσετε την ενότητα Φόρμες, προσθέστε στον ρόλο του το <strong>Ανάγνωση των απαντήσεων φορμών σε εργασίες που μπορείτε να δείτε</strong>.',
        'work_heading' => 'Η προβολή Εργασίας',
        'work_body' => 'Μια εργασία με υλικό εργασίας - λίστες ελέγχου, φόρμες ή διαδικασίες - έχει μια ενότητα <strong>Εργασία</strong> που τα συγκεντρώνει: σε τι χρησιμεύει η εργασία και για ποια ημέρα προορίζεται, την πρόοδο (<em>3 από 5 ολοκληρωμένα</em>, με μέτρηση των βημάτων λίστας ελέγχου και των υποχρεωτικών φορμών), τις οδηγίες, τις διαδικασίες, τις λίστες ελέγχου και τις φόρμες της - και το <strong>Ολοκλήρωση</strong>, που κάνει τις ίδιες ερωτήσεις με το πλαίσιο κατάστασης. Στη διάταξη με καρτέλες του μεγάλου παραθύρου είναι η καρτέλα <strong>Εργασία</strong> και μια εργασία με υλικό ανοίγει εκεί - αποεπιλέξτε το <em>Άνοιγμα εδώ</em> στην καρτέλα αν προτιμάτε να μην ανοίγει· στη διάταξη δύο στηλών βρίσκεται στη φαρδιά στήλη· στο πλευρικό πάνελ είναι στη σειρά. Στο <strong>Σύστημα &rarr; Προτιμήσεις</strong> μπορείτε να συμπτύξετε τις κενές Λίστες ελέγχου, Φόρμες, Διαδικασίες και Ενέργειες παρακολούθησης σε έναν τίτλο όπως <em>Φόρμες (0)</em>, που ανοίγει με ένα κλικ.',
        'work_procedures' => 'Με ενεργό το <strong>Διαδικασίες σε εργασίες</strong> (Ρυθμίσεις &rarr; Λίστες ελέγχου), μια εργασία μπορεί να αναφέρει <strong>άρθρα της Γνωσιακής βάσης</strong> ως διαδικασία, που διαβάζονται επιτόπου. Καθένα ακολουθεί τη δική του πρόσβαση στη Γνωσιακή βάση: όποιος δεν μπορεί να διαβάσει ένα άρθρο βλέπει ότι υπάρχει διαδικασία, όχι τι λέει. Οι εκτελέσεις μιας επαναλαμβανόμενης εργασίας ακολουθούν οι ίδιες τις ίδιες διαδικασίες. Όταν ολοκληρώνεται μια εκτέλεση, το κείμενο κάθε άρθρου <em>όπως ήταν</em> φυλάσσεται μαζί της, ώστε η μεταγενέστερη επεξεργασία του άρθρου να μην ξαναγράφει ποτέ το υλικό βάσει του οποίου έγινε η εργασία - η αναφορά τεκμηρίωσης απαριθμεί αυτό το κείμενο μία φορά στο <strong>Διαδικασίες που χρησιμοποιήθηκαν</strong>.',
        'work_followups' => '<strong>Ενέργειες παρακολούθησης</strong>: όταν ένας έλεγχος εντοπίζει κάτι προς διόρθωση, δημιουργήστε μια <strong>εργασία</strong> ή ένα <strong>αίτημα</strong> για αυτό από την προβολή Εργασίας - η <em>Παρακολούθηση</em> σε ένα αποτυχημένο βήμα ή μια υποβληθείσα φόρμα συμπληρώνει από πού προήλθε - ή συσχετίστε ένα που υπάρχει ήδη. Καθένα δείχνει αν είναι ακόμη ανοιχτό. Η ολοκλήρωση του ελέγχου δεν περιμένει τη διόρθωση, εκτός αν το ορίζουν οι Ρυθμίσεις &rarr; Τεκμηρίωση: από προεπιλογή ο έλεγχος μπορεί να έχει ολοκληρωθεί ενώ η αποκατάσταση συνεχίζεται. Ένα αίτημα παρακολούθησης δημιουργείται από εσάς, ως αιτούντα, όπως κάθε αίτημα που δημιουργείτε με το χέρι.',
        'work_period' => 'Οι <strong>Επαναλαμβανόμενοι έλεγχοι</strong> μπορούν να ορίζουν τι καλύπτει κάθε εκτέλεση και πότε λήγει: το <em>Κάθε εκτέλεση ελέγχει</em> την ημέρα για την οποία προορίζεται, την προηγούμενη ημέρα (τα αντίγραφα ασφαλείας της χθεσινής νύχτας) ή ό,τι έχει γίνει από την προηγούμενη εκτέλεση· το <em>Κάθε εκτέλεση λήγει</em> την ίδια ημέρα, μερικές ημέρες αργότερα ή την επόμενη εργάσιμη. Ένας έλεγχος Σαββάτου με προθεσμία τη Δευτέρα που ολοκληρώνεται τη Δευτέρα είναι <strong>εγκαίρως</strong> στην αναφορά τεκμηρίωσης· αν ολοκληρωθεί την Τρίτη, είναι με καθυστέρηση. Σε μια φόρμα, μια επιλογή μπορεί να σημανθεί ως <strong>Εξαίρεση</strong> στον σχεδιαστή φορμών - Προειδοποίηση, Αποτυχία - και η επιλογή της καταχωρεί την απάντηση στις εξαιρέσεις της εκτέλεσης στην αναφορά τεκμηρίωσης.',
        'forms_heading' => 'Φόρμες που χρειάζεται μια εργασία',
        'forms_body' => 'Με ενεργό το <strong>Φόρμες σε εργασίες</strong> (Ρυθμίσεις &rarr; Λίστες ελέγχου), μια εργασία μπορεί να απαιτεί φόρμες από την ενότητα Φόρμες - ας πούμε έναν ημερήσιο έλεγχο αντιγράφων ασφαλείας με OK / Προειδοποίηση / Αποτυχία και μια εξήγηση. Προσθέστε μία στο <strong>Φόρμες</strong> στο παράθυρο της εργασίας και επιλέξτε <strong>Υποχρεωτικό</strong> (η εργασία δεν μπορεί να ολοκληρωθεί μέχρι να υποβληθεί), <strong>Υποχρεωτικό (με προειδοποίηση)</strong> (μπορεί, και καταγράφεται) ή <strong>Προαιρετικό</strong>. Σε μια επαναλαμβανόμενη εργασία κάθε νέα εκτέλεση απαιτεί τις ίδιες φόρμες, αναπάντητες - οι προηγούμενες απαντήσεις δεν μεταφέρονται ποτέ.',
        'forms_fill' => 'Η <strong>Συμπλήρωση</strong> ανοίγει τη φόρμα για αυτή την εκτέλεση επιτόπου, στην προβολή Εργασίας, με όλες τις ερωτήσεις, τις συνθήκες και τους ελέγχους της (το <em>Άνοιγμα σε νέα καρτέλα</em> της δίνει δική της σελίδα). Η <strong>Αποθήκευση πρόχειρου</strong> τη διατηρεί για αργότερα και το πρόχειρο ανήκει στην εκτέλεση, ώστε να μπορεί να το συνεχίσει ένας συνάδελφος· η εργασία δείχνει ποιος το αποθήκευσε τελευταίος. Αν κάποιος άλλος αποθηκεύσει ενώ εσείς την έχετε ανοιχτή, τίποτα δεν αντικαθίσταται: ενημερώνεστε για το ποιος και πότε, οι απαντήσεις σας παραμένουν στην οθόνη και επιλέγετε αν θα χρησιμοποιήσετε τις δικές του ή θα κρατήσετε τις δικές σας. Η <strong>Υποβολή</strong> συνδέει τις απαντήσεις με αυτή την εκτέλεση - χωρίς αριθμούς αναφοράς προς αντιγραφή - και η <strong>Διόρθωση</strong> τις αντικαθιστά αργότερα, διατηρώντας στο αρχείο την προηγούμενη υποβολή.',
        'forms_complete' => 'Η ολοκλήρωση της εργασίας ελέγχει τις υποχρεωτικές φόρμες της με τον ίδιο τρόπο που ελέγχει τα βήματα της λίστας ελέγχου, όπως κι αν ολοκληρωθεί - από το πλαίσιο κατάστασης, με μεταφορά της κάρτας, με επιλογή μιας υποεργασίας ή μέσω του API. Ολοκλήρωση σημαίνει ότι ο έλεγχος έγινε και καταγράφηκε: μια απάντηση Προειδοποίηση ή Αποτυχία παραμένει ακριβώς αυτό στην αναφορά τεκμηρίωσης, που απαριθμεί τις φόρμες και τις απαντήσεις κάθε εκτέλεσης και διαθέτει ένα <strong>CSV απαντήσεων φορμών</strong>.',
        'forms_access' => 'Η συμπλήρωση μιας φόρμας σε εργασία απαιτεί πρόσβαση στις Φόρμες, όπως στη σελίδα Φόρμες. Η ανάγνωση των απαντήσεων απαιτεί πρόσβαση στις Φόρμες <em>ή</em> το δικαίωμα ρόλου <strong>Ανάγνωση των απαντήσεων φορμών σε εργασίες που μπορείτε να δείτε</strong> - το να βλέπετε την εργασία δεν αρκεί από μόνο του. Χωρίς κανένα από τα δύο, βλέπετε ότι μια φόρμα υποβλήθηκε, από ποιον και πότε, αλλά όχι τις απαντήσεις της - στο παράθυρο της εργασίας, στην αναφορά τεκμηρίωσης και στο CSV της εξίσου.',
        'forms_note' => 'Μια υποβολή που έγινε για μια εργασία είναι το αρχείο αυτής της εκτέλεσης, επομένως δεν μπορεί να διαγραφεί από την ενότητα Φόρμες, και ούτε μια φόρμα με τέτοιες υποβολές μπορεί να διαγραφεί - κάντε την ανενεργή. Σε εγκατάσταση πολλών εταιρειών εμφανίζεται μόνο στα άτομα που μπορούν να δουν αυτή την εργασία.',
        'nav_settings' => 'Ρυθμίσεις',
        'nav_tips' => 'Γρήγορες συμβουλές',
        'nav_companies' => 'Εταιρείες',
        'companies_heading' => 'Εργασίες και εταιρείες',
        'companies_intro' => 'Σε ποιον πελάτη ανήκει μια εργασία και πώς μετακινείται μία που καταχωρίστηκε σε λάθος εταιρεία.',
        'companies_scope' => 'Κάθε εργασία ανήκει σε ακριβώς μία εταιρεία. Μια εργασία που δημιουργείται από αίτημα παίρνει την εταιρεία του αιτήματος· μια εργασία που δημιουργείτε εσείς παίρνει την εταιρεία στην οποία εργάζεστε τη δεδομένη στιγμή. Βλέπετε πάντα μόνο τις εργασίες των εταιρειών στις οποίες έχετε πρόσβαση.',
        'companies_move' => 'Καταχωρίστηκε σε λάθος πελάτη; Κάντε δεξί κλικ στην εργασία και επιλέξτε <strong>Μετακίνηση σε εταιρεία</strong> — στον πίνακα, στον πίνακα προβολής ή στο χρονολόγιο. Μπορείτε να μετακινήσετε μια εργασία μόνο σε εταιρεία στην οποία έχετε οι ίδιοι πρόσβαση και η μετακίνηση καταγράφεται στο ιστορικό της εργασίας, ώστε να υπάρχει αρχείο του τι μετακινήθηκε και πότε.',
        'companies_subtasks' => 'Οι υποεργασίες μετακινούνται μαζί με τη γονική τους, με μία κίνηση. Μια υποεργασία δεν μπορεί να μετακινηθεί μόνη της, επειδή ανήκε πάντα στην ίδια εταιρεία με την εργασία πάνω από αυτήν - ο διαχωρισμός τους θα άφηνε μια γονική εργασία με θυγατρική που μέρος του προσωπικού σας δεν θα μπορούσε να δει.',
        'companies_links' => 'Μια εργασία που συσχετίζεται με αίτημα ή αλλαγή δεν θα μετακινηθεί από αυτό· ενημερώνεστε ποια συσχέτιση εμποδίζει, ώστε να αφαιρέσετε τη συσχέτιση ή να μετακινήσετε και την άλλη εγγραφή. Μια συσχέτιση με σύμβαση δεν εμποδίζει ποτέ μια μετακίνηση, επειδή οι συμβάσεις δεν ανήκουν σε μία μόνο εταιρεία.',
        'hero_title' => 'Οδηγός ενότητας Εργασίες',
        'hero_subtitle' => 'Σχεδιάστε, αναθέστε και παρακολουθήστε εσωτερική εργασία σε πίνακα Kanban &mdash; με ημερολόγιο, χρονολόγιο, ετικέτες και στήλες ανά κατάσταση.',
        'overview_heading' => 'Επισκόπηση',
        'overview_intro' => 'Η ενότητα Εργασίες είναι ένα ελαφρύ εργαλείο παρακολούθησης εργασίας για την ομάδα του service desk σας. Χρησιμοποιήστε την για τις δουλειές που δεν είναι αιτήματα &mdash; εργασία έργων, εσωτερική διοικητική εργασία, επαναλαμβανόμενες δουλειές, ενέργειες παρακολούθησης &mdash; και δείτε τις ως πίνακα Kanban, ταξινομήσιμη λίστα, ημερολόγιο, χρονολόγιο τύπου Gantt ή υπολογιστικό φύλλο πλήρους οθόνης με δυνατότητα επεξεργασίας. Οι εργασίες μπορούν να συνδέονται με αιτήματα και αλλαγές, να φέρουν ετικέτες και να διαιρούνται σε υποεργασίες.',
        'overview_card1_title' => 'Πίνακας',
        'overview_card1_desc' => 'Ένας πίνακας Kanban με μία στήλη ανά κατάσταση. Σύρετε κάρτες ανάμεσα σε στήλες για να αλλάξετε κατάσταση, σύρετε τις επικεφαλίδες στηλών για αναδιάταξη και προσθέστε γρήγορα εργασίες απευθείας σε μια στήλη.',
        'overview_card2_title' => 'Προβολή λίστας',
        'overview_card2_desc' => 'Οι ίδιες εργασίες ως ταξινομήσιμος πίνακας &mdash; κάντε κλικ σε οποιαδήποτε επικεφαλίδα στήλης για ταξινόμηση κατά τίτλο, κατάσταση, προτεραιότητα, υπεύθυνο, ομάδα ή προθεσμία.',
        'overview_card3_title' => 'Ημερολόγιο',
        'overview_card3_desc' => 'Ένα μηνιαίο πλέγμα που τοποθετεί τις εργασίες κατά προθεσμία. Οι εργασίες πολλών ημερών μπορούν να εμφανίζονται ως ένα μόνο σήμα, ως γραμμή που εκτείνεται ή ως σήμα σε κάθε ημέρα &mdash; η επιλογή είναι δική σας στις Ρυθμίσεις.',
        'overview_card4_title' => 'Χρονολόγιο',
        'overview_card4_desc' => 'Ένα διάγραμμα τύπου Gantt που δείχνει κάθε εργασία ως γραμμή από την ημερομηνία έναρξης έως την προθεσμία της. Σύρετε τις γραμμές για αναπρογραμματισμό, σύρετε τα άκρα για να ορίσετε ημερομηνίες έναρξης και προθεσμίας.',
        'overview_card5_title' => 'Πίνακας',
        'overview_card5_desc' => 'Πλέγμα τύπου Excel με επεξεργασία μέσα στα κελιά &mdash; αλλάξτε κατάσταση, προτεραιότητα, υπεύθυνο, ομάδα ή ημερομηνίες απευθείας στη γραμμή. Οι στήλες, η ταξινόμηση, το φίλτρο και η αναζήτηση διατηρούνται ανά τεχνικό.',
        'overview_card6_title' => 'Ετικέτες',
        'overview_card6_desc' => 'Ετικέτες πολλών τιμών για θέματα που διατρέχουν πολλές εργασίες &mdash; Ασφάλεια, ISO, Περιβάλλον &mdash; με τις οποίες μπορείτε να φιλτράρετε και να αναζητήσετε.',
        'overview_card7_title' => 'Ρυθμίσεις',
        'overview_card7_desc' => 'Ρυθμίστε τις καταστάσεις, τις προτεραιότητες και τις ετικέτες· ελέγξτε την εμφάνιση των εργασιών πολλών ημερών στο ημερολόγιο και τι δείχνει κάθε κάρτα.',
        'overview_tip' => 'Ο πίνακας, η λίστα, το ημερολόγιο και το χρονολόγιο είναι απλώς διαφορετικά παράθυρα προς τις ίδιες εργασίες. Μια αλλαγή σε ένα από αυτά εμφανίζεται σε όλα.',
        'board_heading' => 'Ο πίνακας',
        'board_intro' => 'Ο πίνακας είναι η προεπιλεγμένη προβολή &mdash; μια διάταξη Kanban με μία στήλη για κάθε κατάσταση. Είναι ο ταχύτερος τρόπος να δείτε σε ποιο σημείο βρίσκεται το καθετί και να προωθήσετε την εργασία.',
        'board_columns_heading' => 'Οι στήλες είναι καταστάσεις',
        'board_columns_body' => 'Κάθε στήλη είναι μια κατάσταση που ορίζεται στις Ρυθμίσεις &rarr; Καταστάσεις, εμφανίζεται με τη σειρά εμφάνισης και με το χρώμα της κατάστασης ως τελεία στην επικεφαλίδα. Προσθέστε μια κατάσταση και γίνεται στήλη· δεν υπάρχει ξεχωριστή έννοια «στήλης» για διαχείριση. Για να αναδιατάξετε τις στήλες, απλώς <strong>σύρετε μια επικεφαλίδα στήλης</strong> αριστερά ή δεξιά &mdash; η νέα σειρά αποθηκεύεται.',
        'board_creating_heading' => 'Δημιουργία εργασιών',
        'board_creating_step1' => '<strong>Κάντε κλικ στο + στην επικεφαλίδα μιας στήλης</strong> &mdash; ανοίγει ένα ενσωματωμένο πλαίσιο στο πάνω μέρος αυτής της στήλης.',
        'board_creating_step2' => '<strong>Πληκτρολογήστε έναν τίτλο και πατήστε Enter</strong> &mdash; η εργασία δημιουργείται στην κατάσταση αυτής της στήλης και ανατίθεται σε εσάς. Κάντε κλικ σε αυτήν οποιαδήποτε στιγμή για να συμπληρώσετε τα υπόλοιπα.',
        'board_moving_heading' => 'Μετακίνηση και αναδιάταξη',
        'board_moving_body' => 'Σύρετε μια κάρτα σε άλλη στήλη για να αλλάξετε την κατάστασή της· σύρετέ την πάνω ή κάτω μέσα σε μια στήλη για αναδιάταξη. Μια μοβ γραμμή δείχνει πού θα τοποθετηθεί. Η απόθεση μιας κάρτας σε κατάσταση που έχει σημανθεί ως <em>Κλειστή</em> καταγράφει αυτόματα την ώρα ολοκλήρωσής της.',
        'board_rightclick_heading' => 'Δεξί κλικ σε κάρτα',
        'board_rightclick_body' => 'Το δεξί κλικ σε οποιαδήποτε κάρτα ανοίγει ένα μενού γρήγορων ενεργειών &mdash; ανάθεση σε τεχνικό ή ομάδα, αλλαγή κατάστασης ή προτεραιότητας, ή δημιουργία υποεργασίας &mdash; χωρίς να ανοίξετε καθόλου την κάρτα.',
        'board_rightclick_involve' => 'Για να παρακολουθείτε μια εργασία χωρίς να την έχετε στην ευθύνη σας, κάντε δεξί κλικ σε αυτήν και επιλέξτε <strong>Εμπλοκή μου</strong>: προστίθεστε στα <strong>Εμπλεκόμενα</strong> άτομά της και ενημερώνεστε όταν αλλάζει. Το <strong>Διακοπή εμπλοκής</strong> σας αφαιρεί ξανά. Δεν προσφέρεται στις δικές σας εργασίες, τις οποίες ήδη έχετε στην ευθύνη σας.',
        'board_search_heading' => 'Αναζήτηση και φίλτρα',
        'board_search_body' => 'Η πλαϊνή στήλη διαθέτει πλαίσιο <strong>Αναζήτησης</strong> (φιλτράρει καθώς πληκτρολογείτε, με αντιστοίχιση στον τίτλο και την περιγραφή &mdash; και στα ονόματα ετικετών αν είναι ενεργοποιημένο) καθώς και φίλτρα για <strong>Οι εργασίες μου / Όλες οι εργασίες</strong>, <strong>Ομάδα</strong>, <strong>Τεχνικός</strong> και, όταν είναι ενεργοποιημένο, <strong>Ετικέτα</strong>. Τα φίλτρα και η αναζήτηση ισχύουν και για την προβολή λίστας. Επιλέξτε <strong>Απόκρυψη ολοκληρωμένων</strong> για να παραλείψετε κάθε εργασία σε κλειστή κατάσταση - στον πίνακα αυτό κρύβει και τις στήλες Ολοκληρωμένων. Η επιλογή απομνημονεύεται για εσάς και μια εργασία που έχει ολοκληρωθεί δεν εμφανίζεται ποτέ ως <em>Εκπρόθεσμη</em>.',
        'board_subtasks' => 'Οι υποεργασίες μιας εργασίας εμφανίζονται κάτω από την κάρτα της - κάντε κλικ σε μία για να την ανοίξετε. Μέσα σε μια εργασία, σύρετε μια υποεργασία από τη λαβή της <strong>&#8942;&#8942;</strong> για να αλλάξετε τη σειρά. Επιλέξτε ποιες υποεργασίες εμφανίζουν οι κάρτες στο <strong>Υποεργασίες στις κάρτες</strong> της πλαϊνής στήλης: <strong>Όλες</strong>, <strong>Ανοιχτές</strong> (μόνο όσες απομένουν) ή <strong>Καμία</strong> (μόνο το πλήθος). Κάντε κλικ στο πλήθος μιας κάρτας, όπως <strong>1/4</strong>, για να εμφανίσετε ή να κρύψετε τις υποεργασίες μόνο αυτής της κάρτας, ό,τι κι αν λέει η ρύθμιση. Και τα δύο απομνημονεύονται για εσάς.',
        'board_live' => '<strong>Ζωντανές ενημερώσεις.</strong> Ο πίνακας και μια ανοιχτή εργασία ενημερώνονται με τις αλλαγές των άλλων μέσα σε περίπου 15 δευτερόλεπτα - μια κάρτα που μετακινήθηκε, μετονομάστηκε, προστέθηκε ή ολοκληρώθηκε. Μια κάρτα που σύρετε, ένα ανοιχτό μενού ή ένα πεδίο στο οποίο πληκτρολογείτε δεν ξανασχεδιάζεται ποτέ κάτω από τα χέρια σας· μια ανοιχτή εργασία δείχνει αντί γι\' αυτό <strong>Ενημερώθηκε από κάποιον άλλο μόλις τώρα &middot; Ανανέωση</strong>. Το <strong>Προτιμήσεις &rarr; Ζωντανές ενημερώσεις</strong> ορίζει πόσο συχνά ή τις απενεργοποιεί.',
        'board_card_order' => 'Χρησιμοποιήστε το <strong>Σειρά καρτών</strong> στο αριστερό πάνελ για να επιλέξετε πώς τοποθετούνται οι κάρτες μέσα σε κάθε στήλη. Η <strong>Χειροκίνητη</strong> είναι η σειρά στην οποία σύρθηκαν οι κάρτες, κοινή για όλους. Η <strong>Προθεσμία</strong> βάζει πρώτες τις εκπρόθεσμες εργασίες, μετά όσες λήγουν σήμερα και μετά τις υπόλοιπες κατά ημερομηνία, με τις εργασίες χωρίς προθεσμία στο τέλος - μόνο για εσάς και χωρίς να αλλάζει η χειροκίνητη σειρά, που επιστρέφει όπως ήταν όταν γυρίσετε πίσω. Όσο η ταξινόμηση γίνεται κατά προθεσμία μπορείτε ακόμη να σύρετε μια κάρτα σε άλλη στήλη· για να αναδιατάξετε κάρτες μέσα σε μια στήλη, μεταβείτε στη Χειροκίνητη. Η επιλογή σας απομνημονεύεται.',
        'board_columns_by_analyst' => 'Χρησιμοποιήστε το <strong>Στήλες &rarr; Τεχνικός</strong> στο αριστερό πάνελ για να δείτε μία στήλη ανά άτομο (πρώτη η δική σας, μετά η <em>Χωρίς ανάθεση</em>), με κάθε κάρτα να δείχνει την κατάστασή της. Η μεταφορά μιας κάρτας στη στήλη κάποιου άλλου αναθέτει την εργασία σε αυτόν. Η επιλογή σας απομνημονεύεται.',
        'board_tip' => 'Επιλέξτε τι δείχνει κάθε κάρτα &mdash; προτεραιότητα, υπεύθυνο, ομάδα, ημερομηνίες, απόσπασμα περιγραφής, πρόοδο υποεργασιών, ετικέτες &mdash; στις Ρυθμίσεις &rarr; Κάρτα, ώστε να σαρώνετε τις εργασίες χωρίς να τις ανοίγετε.',
        'list_heading' => 'Προβολή λίστας',
        'list_intro' => 'Η λίστα είναι το δίδυμο των δεδομένων του πίνακα &mdash; οι ίδιες εργασίες ως ταξινομήσιμος πίνακας. Μεταβείτε σε αυτήν με τον διακόπτη Προβολής στην πλαϊνή στήλη.',
        'list_body' => 'Κάντε κλικ σε οποιαδήποτε επικεφαλίδα στήλης &mdash; Τίτλος, Κατάσταση, Προτεραιότητα, Υπεύθυνος, Ομάδα, Προθεσμία &mdash; για ταξινόμηση με βάση αυτήν· κάντε κλικ ξανά για αντιστροφή της κατεύθυνσης. Η αναζήτηση και τα φίλτρα της πλαϊνής στήλης λειτουργούν ακριβώς όπως στον πίνακα, ώστε να περιορίσετε τη λίστα και μετά να ταξινομήσετε ό,τι απομένει. Κάντε κλικ σε μια γραμμή για να ανοίξετε την εργασία.',
        'list_tip' => 'Η λίστα είναι το σημείο για να βρείτε μια εργασία της οποίας η κατάσταση δεν έχει στήλη στον πίνακα (για παράδειγμα μια προσαρμοσμένη κατάσταση «Icebox») &mdash; η λίστα δείχνει κάθε εργασία ανεξάρτητα από την κατάσταση.',
        'calendar_heading' => 'Προβολή ημερολογίου',
        'calendar_intro' => 'Το ημερολόγιο τοποθετεί τις εργασίες σε ένα πλέγμα ημερομηνιών ώστε να βλέπετε με μια ματιά προθεσμίες και φόρτο εργασίας. Οι εργασίες χρωματίζονται ανάλογα με την κατάστασή τους.',
        'calendar_body' => 'Η γραμμή εργαλείων έχει <strong>Σήμερα</strong>, προηγούμενο / επόμενο και έναν διακόπτη προβολής <strong>Μήνας / Εβδομάδα / Ημέρα</strong> στα δεξιά. Ο <em>Μήνας</em> είναι το γνώριμο πλέγμα 4&ndash;6 εβδομάδων· η <em>Εβδομάδα</em> εστιάζει σε μία γραμμή επτά ημερών που απλώνεται σε όλη την οθόνη· η <em>Ημέρα</em> περιορίζεται σε μία ημερομηνία και απαριθμεί κάθε εργασία που πέφτει σε αυτήν ως γραμμή καρτών. Το προηγούμενο / επόμενο προχωρά κατά μήνα, εβδομάδα ή ημέρα ανάλογα με την ενεργή προβολή.',
        'calendar_sidebar' => 'Η πλαϊνή στήλη δείχνει ένα υπόμνημα χρωμάτων, τα ίδια φίλτρα Δικές μου / Όλες / Ομάδα / Τεχνικός με τον πίνακα και ένα πάνελ <strong>Τρόπος εμφάνισης διάρκειας</strong> με σύνδεσμο Αλλαγή απευθείας προς τις ρυθμίσεις Ημερολογίου.',
        'calendar_click_heading' => 'Κλικ σε εργασία',
        'calendar_click_body' => 'Το κλικ σε σήμα, γραμμή ή γραμμή προβολής ημέρας μιας εργασίας ανοίγει ένα συρόμενο <strong>γρήγορο πάνελ</strong> στα δεξιά του ημερολογίου &mdash; παραμένετε εκεί που είστε. Ο τίτλος, η κατάσταση, η προτεραιότητα, ο υπεύθυνος, η ομάδα και οι ημερομηνίες επεξεργάζονται όλα στο πάνελ· το εικονίδιο εκκίνησης στο πάνω μέρος ανοίγει τον πλήρη επεξεργαστή του πίνακα ελέγχου όταν χρειάζεστε περιγραφή με μορφοποίηση, υποεργασίες ή σχόλια.',
        'calendar_multiday_heading' => 'Πώς σχεδιάζονται οι εργασίες πολλών ημερών',
        'calendar_multiday_body' => 'Μια εργασία με ημερομηνία έναρξης προγενέστερη της προθεσμίας της καλύπτει ένα εύρος ημερών. Ο τρόπος εμφάνισης αυτού του εύρους ορίζεται μία φορά, ανά εγκατάσταση, στις Ρυθμίσεις &rarr; Ημερολόγιο:',
        'calendar_field_deadline' => '<strong>Σήμα προθεσμίας</strong> &mdash; ένα σήμα μόνο στην ημέρα της προθεσμίας. Η πιο συγκρατημένη επιλογή· ολόκληρο το εύρος φαίνεται ακόμη στο χρονολόγιο.',
        'calendar_field_span' => '<strong>Γραμμή που εκτείνεται</strong> &mdash; μία συνεχής γραμμή σε όλο το εύρος, με αναδίπλωση στις γραμμές εβδομάδων. Ιδανική για να βλέπετε τη διάρκεια.',
        'calendar_field_everyday' => '<strong>Κάθε ημέρα</strong> &mdash; ένα σήμα σε κάθε κελί ημέρας που καλύπτει η εργασία. Πλήρες, αλλά οι μεγάλες εργασίες μπορούν να γεμίσουν το πλέγμα.',
        'calendar_note' => 'Μια εργασία που έχει μόνο προθεσμία εμφανίζεται πάντα ως ένα σήμα σε εκείνη την ημερομηνία, όποια κι αν είναι η επιλεγμένη λειτουργία.',
        'timeline_heading' => 'Προβολή χρονολογίου',
        'timeline_intro' => 'Το χρονολόγιο είναι ένα διάγραμμα τύπου Gantt. Κάθε εργασία είναι μια οριζόντια γραμμή από την ημερομηνία έναρξης έως την προθεσμία της, ώστε να βλέπετε επικαλύψεις, κενά και διάρκειες.',
        'timeline_body' => 'Μια εργασία με μόνο προθεσμία εμφανίζεται ως γραμμή μίας ημέρας. Οι γραμμές μπορούν να ομαδοποιηθούν κατά <strong>Υπεύθυνο</strong>, <strong>Κατάσταση</strong> ή να εμφανίζονται χωρίς ομαδοποίηση &mdash; επιλέξτε από την πλαϊνή στήλη. Ένας διακεκομμένος δείκτης δείχνει το σήμερα, η στήλη ονομάτων εργασιών και η κεφαλίδα ημερομηνιών μένουν στη θέση τους καθώς κυλάτε, και το πλέγμα ημερών προσαρμόζεται αυτόματα στην οθόνη: τα σύντομα εύρη απλώνονται από άκρη σε άκρη, ενώ τα μεγαλύτερα κρατούν κάθε ημέρα σε άνετο μέγεθος και κυλούν οριζόντια.',
        'timeline_drag_heading' => 'Σύρετε τις γραμμές για αναπρογραμματισμό',
        'timeline_drag_body' => 'Οι γραμμές είναι ζωντανοί επεξεργαστές. Τοποθετήστε τον δείκτη πάνω από μία και εμφανίζονται ημιδιαφανείς λαβές και στα δύο άκρα:',
        'timeline_field_body' => '<strong>Σύρετε το σώμα της γραμμής</strong> &mdash; μετακινούνται και η ημερομηνία έναρξης και η προθεσμία κατά τον ίδιο αριθμό ημερών. Η εργασία μετακινείται ολόκληρη χωρίς να αλλάξει η διάρκειά της.',
        'timeline_field_left' => '<strong>Σύρετε το αριστερό άκρο</strong> &mdash; αλλάζει μόνο η ημερομηνία έναρξης. Χρήσιμο για να φέρετε την έναρξη νωρίτερα ή να την ωθήσετε αργότερα, ενώ η προθεσμία μένει ίδια.',
        'timeline_field_right' => '<strong>Σύρετε το δεξί άκρο</strong> &mdash; αλλάζει μόνο η προθεσμία. Σε εργασία με μόνο προθεσμία (χωρίς ημερομηνία έναρξης), η παλιά προθεσμία γίνεται η νέα ημερομηνία έναρξης, ώστε η γραμμή να μεγαλώσει σε κανονικό εύρος αντί να πηδήξει σε θέση μίας ημέρας στο νέο άκρο.',
        'timeline_snap_note' => 'Οι μεταφορές προσαρμόζονται σε ολόκληρες ημέρες. Ένα σύντομο κλικ χωρίς μεταφορά σε μια γραμμή ανοίγει και πάλι την εργασία &mdash; κάτω από όριο κίνησης 3px θεωρείται κλικ, όχι μεταφορά.',
        'timeline_rightclick_heading' => 'Δεξί κλικ για γρήγορες ενέργειες',
        'timeline_rightclick_body' => 'Δεξί κλικ σε οποιαδήποτε γραμμή ανοίγει το ίδιο μενού περιβάλλοντος που χρησιμοποιεί ο πίνακας &mdash; <strong>Ανάθεση σε τεχνικό</strong>, <strong>Ανάθεση σε ομάδα</strong>, <strong>Αλλαγή κατάστασης</strong>, <strong>Αλλαγή προτεραιότητας</strong> &mdash; χωρίς να ανοίξετε τίποτα. Κάθε υπομενού σημειώνει με τσεκ την τρέχουσα τιμή της εργασίας.',
        'timeline_click_heading' => 'Κλικ σε γραμμή',
        'timeline_click_body' => 'Ένα κανονικό κλικ σε μια γραμμή (ή στη στήλη ονομάτων εργασιών αριστερά) ανοίγει το ίδιο συρόμενο γρήγορο πάνελ που χρησιμοποιεί το ημερολόγιο, στα δεξιά του χρονολογίου. Επεξεργαστείτε τα καθημερινά πεδία επιτόπου ή πατήστε το εικονίδιο εκκίνησης στο πάνω μέρος του πάνελ για να μεταβείτε στον πλήρη επεξεργαστή του πίνακα ελέγχου.',
        'table_heading' => 'Προβολή πίνακα',
        'table_intro' => 'Η προβολή Πίνακα είναι ένα πλέγμα πλήρους οθόνης τύπου Excel &mdash; μία γραμμή ανά εργασία, με κελιά που επεξεργάζονται. Είναι το ταχύτερο σημείο για να διαλέξετε προτεραιότητες σε μια λίστα, να αλλάξετε μαζικά πεδία ή να φτιάξετε την ακριβή διάταξη στηλών στην οποία θέλετε να εργάζεστε.',
        'table_edit_heading' => 'Επεξεργασία απευθείας στο κελί',
        'table_open_heading' => 'Άνοιγμα μιας εργασίας',
        'table_open_body' => 'Κάθε γραμμή ξεκινά με ένα εικονίδιο <strong>ανοίγματος</strong> (ή κάντε δεξί κλικ σε μια γραμμή και επιλέξτε <strong>Άνοιγμα</strong>). Ανοίγει το ίδιο πάνελ με το Ημερολόγιο και το Χρονοδιάγραμμα, πάνω από τον πίνακα, ώστε τα φίλτρα, η ταξινόμηση και η θέση σας να μένουν ως έχουν. Το πάνελ είναι μια γρήγορη ματιά - κατάσταση, ημερομηνίες, υπεύθυνος και περιγραφή - με ένα κουμπί <strong>Επεξεργασία</strong> που το μετατρέπει στην πλήρη εργασία, επιτόπου. Εναλλακτικά, επιλέξτε <strong>Η πλήρης εργασία</strong> στις <strong>Προτιμήσεις &rarr; Άνοιγμα εργασίας</strong> για να βλέπετε πάντα την πλήρη εργασία, όπως στον πίνακα εργασιών. Το εικονίδιο εκκίνησης στο επάνω μέρος μεταβαίνει στην εργασία στον πίνακα εργασιών. Κάντε Ctrl-κλικ ή μεσαίο κλικ στο εικονίδιο για να ανοίξει η πλήρης εργασία σε νέα καρτέλα. Το κλικ σε ένα κελί εξακολουθεί να το επεξεργάζεται, όπως πριν.',
        'table_edit_body' => 'Οι περισσότερες στήλες εμφανίζουν επεξεργάσιμο στοιχείο αντί για στατικό κείμενο. Επιλέξτε νέα κατάσταση ή προτεραιότητα από την αναπτυσσόμενη λίστα, αλλάξτε τον υπεύθυνο ή την ομάδα, πληκτρολογήστε νέο τίτλο, πληκτρολογήστε ή επιλέξτε νέα ημερομηνία έναρξης / προθεσμία &mdash; κάθε κελί αποθηκεύεται με την αλλαγή, χωρίς κουμπί Αποθήκευσης να ψάχνετε. Η κατάσταση και η προτεραιότητα εμφανίζουν μια έγχρωμη κουκκίδα που ενημερώνεται επιτόπου μετά την αποθήκευση.',
        'table_views_heading' => 'Αποθηκευμένες προβολές',
        'table_views_body' => 'Μόλις ο πίνακας δείχνει όπως θέλετε &mdash; με τις σωστές στήλες, ταξινομημένος και φιλτραρισμένος &mdash; το <strong>Αποθήκευση προβολής</strong> στη γραμμή εργαλείων κρατά αυτή τη διάταξη με ένα όνομα, και το <strong>Προβολές</strong> δίπλα του ανοίγει τη βιβλιοθήκη. Μια προβολή μπορεί να είναι ορατή <strong>μόνο σε εσάς</strong>, σε <strong>μία από τις ομάδες σας</strong> ή σε <strong>όλους</strong>. Το αστέρι την κάνει προεπιλογή σας, ώστε ο πίνακας να ανοίγει με αυτήν. Η βιβλιοθήκη μπορεί να αναζητηθεί με όνομα, περιγραφή ή δημιουργό και να εμφανιστεί ως λίστα ή ως κάρτες.',
        'table_views_note' => 'Αποθηκεύονται οι στήλες, η ταξινόμηση και τα φίλτρα. Το πλαίσιο αναζήτησης σκόπιμα δεν αποθηκεύεται, γιατί η αναζήτηση είναι μια ερώτηση που κάνετε μία φορά και όχι ένας τρόπος που θέλετε να βλέπετε τα πράγματα. Οι ίδιες προβολές υπάρχουν στους πίνακες Παγίων, Ημερολογίου και Διαχείρισης αλλαγών, και ο καθένας κρατά τις δικές του.',
        'table_columns_heading' => 'Στήλες: εμφάνιση, απόκρυψη, αναδιάταξη',
        'table_columns_body' => 'Κάντε κλικ στο κουμπί <strong>Στήλες</strong> στη γραμμή εργαλείων για να ανοίξει ένα συρτάρι με όλες τις στήλες που γνωρίζει ο πίνακας. Επιλέξτε όσες θέλετε να φαίνονται και σύρετε τις γραμμές για αναδιάταξη. Η λαβή μεταφοράς στην κεφαλίδα μιας στήλης αναδιατάσσει επίσης τις στήλες απευθείας. Η εμφάνιση και η σειρά αποθηκεύονται στον λογαριασμό σας, ώστε την επόμενη φορά που θα ανοίξετε τον πίνακα να είναι όπως τον αφήσατε.',
        'table_sort_heading' => 'Ταξινόμηση, φίλτρο, αναζήτηση',
        'table_field_sort' => '<strong>Ταξινόμηση</strong> &mdash; κάντε κλικ σε οποιαδήποτε κεφαλίδα στήλης για να ταξινομήσετε με βάση αυτήν. Κάντε ξανά κλικ για να αντιστρέψετε την κατεύθυνση. Η ενεργή ταξινόμηση αποθηκεύεται ανά τεχνικό μαζί με τη διάταξη των στηλών.',
        'table_field_filter' => '<strong>Φίλτρο</strong> &mdash; κάντε κλικ στο εικονίδιο του χωνιού σε μια κεφαλίδα στήλης για να εμφανιστεί μια λίστα με τετραγωνίδια, σαν στο Excel, με κάθε τιμή που περιέχει πραγματικά η στήλη. Αποεπιλέξτε όσες δεν θέλετε. Οι αριθμοί στη λίστα δείχνουν πόσες γραμμές ταιριάζουν σε κάθε τιμή. Τα ενεργά φίλτρα δείχνουν το χωνί σε μωβ χρώμα.',
        'table_field_search' => '<strong>Αναζήτηση</strong> &mdash; το πλαίσιο αναζήτησης της γραμμής εργαλείων ταιριάζει με το κείμενο κάθε ορατής στήλης. Φιλτράρει καθώς πληκτρολογείτε.',
        'table_field_reset' => '<strong>Επαναφορά</strong> &mdash; το κουμπί Επαναφορά της γραμμής εργαλείων καθαρίζει όλα τα φίλτρα και το πλαίσιο αναζήτησης και επαναφέρει την ταξινόμηση.',
        'table_export_heading' => 'Δεξί κλικ και εξαγωγή',
        'table_export_body' => 'Το δεξί κλικ σε μια γραμμή ανοίγει το ίδιο μενού περιβάλλοντος που χρησιμοποιούν ο πίνακας εργασιών και το χρονοδιάγραμμα &mdash; Ανάθεση σε τεχνικό / ομάδα, Αλλαγή κατάστασης / προτεραιότητας. Το κουμπί <strong>CSV</strong> στη γραμμή εργαλείων κατεβάζει την τρέχουσα προβολή (με τις ορατές στήλες, την αναζήτηση, τα φίλτρα και την ταξινόμηση) ως CSV UTF-8 που το Excel ανοίγει σωστά.',
        'table_tip' => 'Η ταξινόμηση και το φίλτρο <em>δεν</em> εκτελούνται ξανά ενώ επεξεργάζεστε ένα κελί &mdash; θα σας έκλεβαν την εστίαση. Η αλλαγή σας αποθηκεύεται αμέσως. Όταν αλλάξετε την ταξινόμηση, αλλάξετε ένα φίλτρο ή πατήσετε Επαναφορά, θα χρησιμοποιηθεί η νέα τιμή.',
        'panel_heading' => 'Το πάνελ εργασίας',
        'panel_intro' => 'Το κλικ σε μια εργασία ανοίγει ένα πάνελ που γλιστρά από τα δεξιά. Κάθε πεδίο αποθηκεύεται αυτόματα μόλις το αλλάξετε &mdash; δεν υπάρχει κουμπί Αποθήκευσης. Το πάνελ του πίνακα εργασιών είναι ο πλήρης επεξεργαστής. Το ημερολόγιο και το χρονοδιάγραμμα ανοίγουν ένα ελαφρύτερο <em>γρήγορο πάνελ</em> με τα καθημερινά πεδία και ένα εικονίδιο εκκίνησης που μεταβαίνει στον πλήρη επεξεργαστή όταν χρειάζεστε περιγραφή με μορφοποίηση, υποεργασίες ή σχόλια.',
        'panel_field_title' => '<strong>Τίτλος</strong> &mdash; κάντε κλικ και πληκτρολογήστε στο επάνω μέρος του πάνελ.',
        'panel_field_status' => '<strong>Κατάσταση &amp; Προτεραιότητα</strong> &mdash; αναπτυσσόμενες λίστες που προκύπτουν από τις λίστες τιμών που έχετε ρυθμίσει.',
        'panel_field_assignee' => '<strong>Ανατεθειμένος σε &amp; Ομάδα</strong> &mdash; ποιος είναι υπεύθυνος για την εργασία και σε ποια ομάδα ανήκει.',
        'panel_field_contractor' => '<strong>Εξωτερικός συνεργάτης &amp; Επαφή εκεί</strong> &mdash; όταν την εργασία κάνει εξωτερική εταιρεία: ένας προμηθευτής από τις Συμβάσεις και, αν θέλετε, ένα άτομο εκεί. Ο ανατεθειμένος παραμένει το άτομο από εδώ που τους παρακολουθεί. Η επιλογή απαιτεί πρόσβαση στις Συμβάσεις. Μια εταιρεία μπορεί να κρύψει το ζεύγος στις <strong>Εργασίες &rarr; Ρυθμίσεις &rarr; Εμπλεκόμενοι</strong>. Ένας εξωτερικός συνεργάτης που υπάρχει ήδη σε μια εργασία εμφανίζεται τότε μόνο για ανάγνωση.',
        'panel_contractor_note' => 'Το <strong>Έργο εξωτερικού συνεργάτη</strong> εμφανίζει το όνομα της εταιρείας στην κάρτα, και το φίλτρο <strong>Εξωτερικός συνεργάτης</strong> στο αριστερό πάνελ (εμφανίζεται μόλις κάποια εργασία έχει έναν) περιορίζει τον πίνακα σε μία εταιρεία, σε κάθε εργασία με εξωτερικό συνεργάτη ή σε καμία. Τα Έργα μπορούν να στέλνουν email στο άτομο της εταιρείας όταν του ανατίθεται μια εργασία και όταν λήγει η προθεσμία της &mdash; απενεργοποιημένο, εκτός αν κάποιος το ενεργοποιήσει στις Έργα &rarr; Ρυθμίσεις.',
        'panel_field_account' => '<strong>Λογαριασμός</strong> &mdash; για μια εργασία σε έργο, όταν το λογιστικό σχέδιο του οικονομικού σας τμήματος βρίσκεται στο FreeITSM: σε ποιον λογαριασμό μετράει ο χρόνος που καταγράφεται στην εργασία, ή ένας επιμερισμός ανά ποσοστό (70% Εξοπλισμός υπολογιστών, 30% Επαγγελματικές υπηρεσίες). Μια υποεργασία χρησιμοποιεί τον λογαριασμό της γονικής της, εκτός αν έχει δικό της. Η <strong>Αλλαγή</strong> απαιτεί το δικαίωμα αλλαγής του έργου· αν μια αλλαγή μετακινεί όλο τον χρόνο της εργασίας ή μόνο τον χρόνο που καταγράφεται από τότε, ορίζεται στο Έργα &rarr; Ρυθμίσεις &rarr; Προϋπολογισμός.',
        'panel_field_dates' => '<strong>Ημερομηνίες έναρξης &amp; προθεσμίας</strong> &mdash; μαζί ορίζουν το διάστημα που εμφανίζεται στο ημερολόγιο και στο χρονοδιάγραμμα.',
        'panel_field_tags' => '<strong>Ετικέτες</strong> &mdash; επιλογέας με φιλτράρισμα κατά την πληκτρολόγηση. Προσθέστε όσες θέλετε και αφαιρέστε με το &times; σε κάθε ετικέτα.',
        'panel_field_desc' => '<strong>Περιγραφή</strong> &mdash; επεξεργαστής εμπλουτισμένου κειμένου με έντονη γραφή, λίστες και συνδέσμους.',
        'panel_field_links' => '<strong>Συσχετίσεις</strong> &mdash; αναζητήστε και επισυνάψτε σχετικά αιτήματα ή αλλαγές.',
        'panel_links_note' => '<strong>Ένα αίτημα και μία αλλαγή.</strong> Μια εργασία μπορεί να συνδεθεί με ένα μόνο αίτημα και μία μόνο αλλαγή, επομένως τα πλαίσια αναζήτησης παραμένουν ορατά ακόμη και όταν κάτι είναι ήδη συσχετισμένο και προσφέρουν τη συσχέτιση ενός <em>άλλου</em>. Η επιλογή διαφορετικής εγγραφής ζητά πρώτα επιβεβαίωση και αναφέρει τι πρόκειται να αποσυσχετιστεί &mdash; τίποτα δεν αντικαθίσταται χωρίς τη συμφωνία σας. Η ίδια προειδοποίηση εμφανίζεται και από την πλευρά του αιτήματος: η επισύναψη μιας εργασίας που ανήκει ήδη σε άλλο αίτημα την <em>μετακινεί</em> και το αναφέρει πριν το κάνει.',
        'panel_preview_note' => '<strong>Το &#9432; δίπλα σε μια συσχετισμένη εγγραφή</strong> ανοίγει μια κάρτα με τα βασικά στοιχεία χωρίς να φύγετε από την εργασία &mdash; η κατάσταση, η προτεραιότητα ενός αιτήματος, σε ποιον βρίσκεται και ποιος το δημιούργησε. Για μια αλλαγή, η κατάσταση, ο κίνδυνος και το προγραμματισμένο παράθυρο. Είναι μόνο για ανάγνωση σκόπιμα, ώστε μια ματιά να μην καταλήξει σε τυχαία επεξεργασία. Το <strong>Escape</strong> την κλείνει και το <strong>Άνοιγμα</strong> σας μεταφέρει στην ίδια την εγγραφή. Αν λέει ότι η εγγραφή δεν μπορεί να εμφανιστεί, είτε δεν έχετε πρόσβαση σε αυτήν είτε έχει διαγραφεί &mdash; η ίδια απάντηση δίνεται και στις δύο περιπτώσεις σκόπιμα.',
        'panel_field_subtasks' => '<strong>Υποεργασίες</strong> &mdash; χωρίστε την εργασία σε μικρότερα κομμάτια, το καθένα με δικό του υπεύθυνο. Κάθε γραμμή δείχνει ποιος την έχει και τις ημερομηνίες <strong>Έναρξης</strong> και <strong>Προθεσμίας</strong>, που μπορείτε να αλλάξετε επιτόπου. Σύρετε μια γραμμή από τη λαβή <strong>&#8942;&#8942;</strong> για να αλλάξετε τη σειρά. Η πρόοδος εμφανίζεται στη γονική κάρτα, με τις υποεργασίες να αναφέρονται από κάτω.',
        'panel_field_comments' => '<strong>Σχόλια</strong> &mdash; μια διαρκής συζήτηση πάνω στην εργασία. Ένα σχόλιο από ροή εργασιών εμφανίζεται ως γραμμένο από το <strong>Σύστημα</strong>, και το Ιστορικό της εργασίας ονομάζει τη ροή εργασιών που την άλλαξε.',
        'panel_field_work' => '<strong>Έναρξη και λήξη εργασιών</strong> &mdash; πότε η εργασία <em>προγραμματίζεται</em> να γίνει, με επιλογή <strong>Ολοήμερο</strong>. Αυτά εμφανίζονται ίδια για όλους: ένα χρονικό παράθυρο στις 2 μ.μ. είναι στις 2 μ.μ. για όποιον κι αν το βλέπει, όπως ένα παράθυρο συντήρησης.',
        'panel_field_time' => '<strong>Χρόνος</strong> &mdash; πόσο διήρκεσε πραγματικά η εργασία, καταγεγραμμένος ως ξεχωριστές συνεδρίες με σημείωση σε καθεμία και συνολικό άθροισμα. Μια γονική εργασία δείχνει επίσης το σύνολο <em>συμπεριλαμβανομένων των υποεργασιών της</em>. Ο καταγεγραμμένος χρόνος είναι πραγματική χρονική στιγμή, γι\' αυτό εμφανίζεται στη δική σας ζώνη ώρας.',
        'panel_view_note' => 'Η εργασία ανοίγει σε ένα πάνελ στο πλάι του πίνακα εργασιών. Χρησιμοποιήστε το κουμπί <strong>επέκτασης</strong> στη γωνία του για ένα μεγάλο παράθυρο που τοποθετεί το ίδιο περιεχόμενο σε δύο στήλες &mdash; περιγραφή και σχόλια αριστερά, τα σύντομα πεδία δεξιά. Μέσα στο μεγάλο παράθυρο ένα δεύτερο κουμπί αλλάζει σε <strong>καρτέλες</strong>: Λεπτομέρειες, Υποεργασίες, Χρόνος, Σχόλια, Συσχετίσεις και Έγγραφα, καθεμία με τον αριθμό των στοιχείων που περιέχει. Το FreeITSM θυμάται ποια προτιμάτε και μπορείτε επίσης να το ορίσετε στις <em>Προτιμήσεις &rarr; Άνοιγμα εργασίας</em>.',
        'panel_context_note' => '<strong>Δεξί κλικ σε οποιαδήποτε κάρτα</strong> για να φτάσετε στα περισσότερα από αυτά χωρίς να ανοίξετε την εργασία: άνοιγμα, ανάθεση στον εαυτό σας ή σε οποιονδήποτε άλλον, αλλαγή κατάστασης ή προτεραιότητας, ορισμός προθεσμίας, σήμανση ως ολοκληρωμένη, καταγραφή χρόνου, προσθήκη υποεργασίας, αντιγραφή συνδέσμου προς αυτήν ή διαγραφή.',
        'panel_delete_note' => 'Το κουμπί διαγραφής (πάνω δεξιά στο πάνελ) αφαιρεί την εργασία και όλες τις υποεργασίες της &mdash; ζητά πρώτα επιβεβαίωση.',
        'nav_repeats' => 'Επαναλαμβανόμενες εργασίες',
        'repeats_heading' => 'Επαναλαμβανόμενες εργασίες',
        'repeats_intro' => 'Κάποιες δουλειές επιστρέφουν: ένας μηνιαίος έλεγχος αντιγράφων ασφαλείας, μια τριμηνιαία αναθεώρηση πρόσβασης, μια εβδομαδιαία αναφορά. Σε κάθε εργασία μπορεί να οριστεί επανάληψη και το FreeITSM δημιουργεί την επόμενη εμφάνιση για εσάς, αντί να σας αφήνει να θυμάστε.',
        'repeats_cron_warning' => '<strong>Ένα σταθερό πρόγραμμα χρειάζεται μια προγραμματισμένη εργασία στον διακομιστή και τίποτα δεν σας προειδοποιεί αν λείπει.</strong> Οι επαναλήψεις που έχουν οριστεί <em>σε σταθερό πρόγραμμα</em> δημιουργούνται από το <code>cron/task_recurrence.php</code>. Μια νέα εγκατάσταση δεν έχει καθόλου προγραμματισμένες εργασίες, επομένως μέχρι να ρυθμίσει κάποιος αυτήν, ένα σταθερό πρόγραμμα απλώς δεν θα παράγει ποτέ τίποτα &mdash; χωρίς σφάλμα, χωρίς εγγραφή στο αρχείο καταγραφής, απλώς μια επανάληψη που αθόρυβα δεν κάνει τίποτα. Εκτελέστε την <strong>μία φορά την ημέρα</strong>. Οι <strong>Αναφορές &rarr; Αρχεία καταγραφής συστήματος &rarr; Εργασίες παρασκηνίου</strong> δείχνουν αν εκτελείται. Οι επαναλήψεις που έχουν οριστεί <em>μετά την ολοκλήρωση της τρέχουσας</em> δεν επηρεάζονται: δημιουργούνται μέσα στο αίτημα που ολοκληρώνει την προηγούμενη, επομένως λειτουργούν και σε εγκατάσταση χωρίς καμία προγραμματισμένη εργασία.',
        'repeats_setup_heading' => 'Ρύθμιση μιας επανάληψης',
        'repeats_setup_body' => 'Ανοίξτε μια εργασία και βρείτε τις <strong>Επαναλήψεις</strong> στο πάνελ, και μετά κάντε κλικ στο <strong>Ρύθμιση επανάληψης</strong>. Μπορείτε επίσης να κάνετε δεξί κλικ σε μια κάρτα στον πίνακα εργασιών και να επιλέξετε <strong>Ρύθμιση επανάληψης</strong> χωρίς να την ανοίξετε καθόλου. Μια υποεργασία δεν μπορεί να επαναλαμβάνεται μόνη της &mdash; η επανάληψη ανήκει στη δουλειά και όχι σε ένα βήμα μέσα σε αυτήν.',
        'repeats_mode_heading' => 'Δύο τρόποι επανάληψης, και η διαφορά έχει σημασία',
        'repeats_mode_body' => 'Αυτή είναι η πρώτη επιλογή στον επεξεργαστή και αξίζει να τη σκεφτείτε, γιατί οι δύο τρόποι συμπεριφέρονται διαφορετικά όταν η δουλειά καθυστερεί.',
        'repeats_mode_completion' => '<strong>Μετά την ολοκλήρωση της τρέχουσας</strong> &mdash; η επόμενη εμφάνιση δημιουργείται όταν τελειώσετε την τρέχουσα και η ημερομηνία της υπολογίζεται από την ημέρα που πράγματι τελειώσατε. Αυτό εννοούν οι περισσότεροι με το «ένας μηνιαίος έλεγχος»: αν ο έλεγχος του Φεβρουαρίου γίνει στις 5, ο επόμενος πέφτει έναν μήνα μετά τις 5. Δεν δημιουργείται τίποτα όσο η τρέχουσα είναι ακόμη ανοιχτή, επομένως δεν περιμένουν ποτέ δύο ίδιες δουλειές.',
        'repeats_mode_schedule' => '<strong>Σε σταθερό πρόγραμμα</strong> &mdash; οι εμφανίσεις φτάνουν στις ημερομηνίες τους ανεξάρτητα από το αν η προηγούμενη ολοκληρώθηκε. Αυτό χρειάζεται μια αναθεώρηση συμμόρφωσης: ο έλεγχος του Μαρτίου λήγει τον Μάρτιο ακόμη κι αν ο προηγούμενος του Φεβρουαρίου δεν έγινε ποτέ. Οι εμφανίσεις που χάθηκαν συσσωρεύονται αντί να παραλείπονται αθόρυβα, και αν ο διακομιστής ήταν εκτός λειτουργίας για μια εβδομάδα, η εργασία τις συμπληρώνει αντί να τις χάνει.',
        'repeats_pattern_heading' => 'Πόσο συχνά',
        'repeats_pattern_body' => 'Ένα μοτίβο είναι μια συχνότητα και ένα διάστημα &mdash; κάθε N ημέρες, εβδομάδες, μήνες ή έτη &mdash; και, για εβδομαδιαίες και μηνιαίες επαναλήψεις, μια επιλογή ημερών.',
        'repeats_pattern_daily' => '<strong>Ημερήσια</strong> &mdash; κάθε ημέρα ή κάθε N ημέρες.',
        'repeats_pattern_weekly' => '<strong>Εβδομαδιαία</strong> &mdash; κάθε εβδομάδα ή κάθε N εβδομάδες, σε οποιονδήποτε συνδυασμό ημερών της εβδομάδας. Το «Κάθε δεύτερη εβδομάδα τη Δευτέρα και την Πέμπτη» είναι ένας κανόνας, όχι δύο.',
        'repeats_pattern_dom' => '<strong>Μηνιαία, με αριθμό ημέρας</strong> &mdash; η 1η, η 15η, η 28η. Εισαγάγετε <strong>-1</strong> για την τελευταία ημέρα του μήνα ανεξάρτητα από τη διάρκειά του, κάτι που χρειάζονται οι εργασίες τέλους μήνα και δεν μπορεί να γραφτεί ως αριθμός. Ένας αριθμός ημέρας μεγαλύτερος από έναν σύντομο μήνα &mdash; η 31η του Φεβρουαρίου &mdash; πέφτει στην τελευταία ημέρα του μήνα αντί να παραλείπει τον μήνα.',
        'repeats_pattern_nth' => '<strong>Μηνιαία, με ονομαστική ημέρα της εβδομάδας</strong> &mdash; η πρώτη Δευτέρα, η τρίτη Τετάρτη, η τελευταία Παρασκευή. Επιλέξτε τη θέση και την ημέρα της εβδομάδας. Αν ζητήσετε την πέμπτη μιας ημέρας σε έναν μήνα που έχει μόνο τέσσερις, πέφτει στην τελευταία, ώστε ο μήνας να μην παραλείπεται ποτέ.',
        'repeats_pattern_yearly' => '<strong>Ετήσια</strong> &mdash; κάθε έτος ή κάθε N έτη, προαιρετικά σε έναν επιλεγμένο μήνα, με την ίδια επιλογή αριθμού ημέρας ή ονομαστικής ημέρας της εβδομάδας όπως στη μηνιαία.',
        'repeats_ends_heading' => 'Πότε σταματά',
        'repeats_ends_never' => '<strong>Ποτέ</strong> &mdash; συνεχίζεται μέχρι να τη σταματήσετε.',
        'repeats_ends_date' => '<strong>Σε μια ημερομηνία</strong> &mdash; η τελευταία εμφάνιση είναι η τελευταία που πέφτει πριν ή την ίδια ημέρα με αυτήν την ημερομηνία.',
        'repeats_ends_count' => '<strong>Μετά από ένα πλήθος εμφανίσεων</strong> &mdash; το πλήθος <em>περιλαμβάνει</em> την εργασία στην οποία ορίσατε την επανάληψη. Αν ζητήσετε πέντε, παίρνετε την εργασία μπροστά σας και άλλες τέσσερις.',
        'repeats_carry_heading' => 'Τι μεταφέρεται',
        'repeats_carry_body' => 'Η περιγραφή, οι υποεργασίες, ο ανατεθειμένος, οι ετικέτες, οι συσχετίσεις με αιτήματα και αλλαγές και τα επισυναπτόμενα έγγραφα επιλέγονται ξεχωριστά, επειδή η σωστή απάντηση διαφέρει ανά δουλειά. Η μεταφορά των συνημμένων είναι σωστή για μια λίστα ελέγχου που χρησιμοποιεί τις ίδιες φόρμες κάθε μήνα, και λάθος για έναν έλεγχο που υποτίθεται ότι συγκεντρώνει νέα τεκμήρια κάθε φορά.',
        'repeats_carry_note' => 'Μια νέα εμφάνιση φτάνει πάντα ανοιχτή και ανολοκλήρωτη, ποτέ στην κατάσταση στην οποία έκλεισε η προηγούμενη. Διατηρεί επίσης το διάστημα ανάμεσα στην ημερομηνία έναρξης και την προθεσμία, ώστε μια δουλειά δύο εβδομάδων να παραμένει δύο εβδομάδων.',
        'repeats_when_heading' => 'Πότε εμφανίζεται η επόμενη',
        'repeats_when_body' => 'Μια εμφάνιση δημιουργείται όταν η εργασία μπορεί να <strong>ξεκινήσει</strong>, όχι όταν λήγει. Μια εργασία με ημερομηνία έναρξης δύο εβδομάδες πριν την προθεσμία εμφανίζεται δύο εβδομάδες νωρίτερα. Μια εργασία μόνο με προθεσμία εμφανίζεται την ίδια ημέρα. Σκόπιμα δεν υπάρχει ρύθμιση «ημέρες προειδοποίησης»: ο χρόνος προετοιμασίας είναι η διάρκεια που έχετε ήδη δώσει στην εργασία, κάτι καλύτερο από έναν αριθμό που θα ήταν λάθος για τις μισές.',
        'repeats_when_note' => 'Γι\' αυτό ο πίνακας εργασιών περιέχει πάντα μόνο δουλειά που θα μπορούσατε πράγματι να κάνετε τώρα. Οι μελλοντικές εμφανίσεις ενός σταθερού προγράμματος φαίνονται ακόμη στο <strong>ημερολόγιο</strong>, σχεδιασμένες αχνά χωρίς ακόμη εργασία πίσω τους, ώστε να βλέπετε το πλάνο χωρίς να γεμίζει ο πίνακας με δουλειές που κανείς δεν μπορεί να ξεκινήσει.',
        'repeats_preview_heading' => 'Προεπισκόπηση',
        'repeats_preview_body' => 'Το «Κάθε δεύτερη Τρίτη του μήνα, πέντε φορές» δεν είναι πρόταση που οι περισσότεροι μπορούν να μετατρέψουν σε ημερομηνίες με το μυαλό τους. Η <strong>Προεπισκόπηση</strong>, δίπλα στην Αποθήκευση, απαριθμεί κάθε εμφάνιση που θα παρήγαγαν οι τρέχουσες ρυθμίσεις με τις ημερομηνίες έναρξης και προθεσμίας &mdash; συμπεριλαμβανομένων ρυθμίσεων που δεν έχετε αποθηκεύσει, ώστε να δοκιμάσετε έναν κανόνα πριν τον κρατήσετε. Η εργασία στην οποία βρίσκεστε εμφανίζεται ως η πρώτη εμφάνιση και ό,τι υπάρχει ήδη επισημαίνεται, ώστε η προεπισκόπηση μιας καθιερωμένης επανάληψης να δείχνει τι έχει κάνει καθώς και τι θα κάνει. Μια επανάληψη χωρίς λήξη δείχνει τις πρώτες 25.',
        'repeats_preview_note' => 'Αν οι ρυθμίσεις δεν παράγουν τίποτα, η Προεπισκόπηση το λέει ξεκάθαρα &mdash; συνήθως σημάδι ότι η λήξη ή η ημέρα που επιλέξατε δεν είναι αυτό που εννοούσατε. Μια επανάληψη που ενεργοποιείται μετά την ολοκλήρωση δεν έχει ημερομηνίες να απαριθμήσει, γιατί η επόμενη ημερομηνία της υπολογίζεται από την ημέρα που πράγματι τελειώνει η δουλειά. Η Προεπισκόπηση το εξηγεί αντί να μαντεύει.',
        'repeats_finding_heading' => 'Πώς να βρίσκετε τον δρόμο σας σε μια σειρά',
        'repeats_finding_body' => 'Μια εργασία που ανήκει σε επανάληψη φέρει ένα μικρό εικονίδιο επανάληψης στον πίνακα εργασιών και στο ημερολόγιο, και στο πάνελ δείχνει τη θέση της στη σειρά &mdash; <em>εμφάνιση 3 από 12</em>. Το πάνελ φέρει επίσης έναν σύνδεσμο πίσω στην εργασία από την οποία ξεκίνησε η σειρά, ώστε το πρωτότυπο να είναι ένα κλικ μακριά από οποιαδήποτε εμφάνιση.',
        'repeats_stop_heading' => 'Διακοπή μιας επανάληψης',
        'repeats_stop_body' => 'Η <strong>Διακοπή επανάληψης</strong> τερματίζει τη σειρά και δεν διαγράφει ποτέ τίποτα. Οι εμφανίσεις που έχουν ήδη δημιουργηθεί είναι πραγματική δουλειά, ορισμένες ήδη ολοκληρωμένες, επομένως η απενεργοποίηση μιας επανάληψης σημαίνει «όχι άλλες τέτοιες» και όχι «προσποιηθείτε ότι οι τελευταίοι έξι μήνες δεν έγιναν». Η αλλαγή των ρυθμίσεων και η νέα αποθήκευση αντικαθιστά τον κανόνα για τις μελλοντικές εμφανίσεις και αφήνει τις υπάρχουσες ανέγγιχτες.',
        'repeats_tip' => 'Δεν είστε σίγουροι ποιον τρόπο θέλετε; Αν η καθυστέρηση πρέπει να μετατοπίζει την επόμενη, επιλέξτε <em>μετά την ολοκλήρωση της τρέχουσας</em>. Αν η καθυστέρηση πρέπει να σας αφήνει με δύο να κάνετε, επιλέξτε <em>σε σταθερό πρόγραμμα</em>.',
        'tags_heading' => 'Ετικέτες',
        'tags_intro' => 'Οι ετικέτες είναι ετικέτες πολλαπλών τιμών για θέματα που διασχίζουν τα πάντα &mdash; όσα δεν ταιριάζουν σε μια κατάσταση ή μια προτεραιότητα. Μια εργασία μπορεί να φέρει όσες θέλετε.',
        'tags_body1' => 'Η κατάσταση απαντά «σε ποιο στάδιο βρίσκεται;», η προτεραιότητα «πόσο επείγει;» και μια ετικέτα απαντά «για ποιο θέμα <em>αφορά</em>;» &mdash; Ασφάλεια, ISO, Περιβάλλον και ούτω καθεξής. Επειδή μια εργασία μπορεί να έχει πολλές ετικέτες, μπορείτε να τεμαχίσετε τη δουλειά σας ανά θέμα σε όλες τις καταστάσεις και τους υπευθύνους.',
        'tags_body2' => 'Οι ετικέτες διαχειρίζονται στις Ρυθμίσεις &rarr; Ετικέτες, καθεμία με όνομα και χρώμα. Πέντε επιλογές εμφάνισης εκεί ελέγχουν αν μπορούν να δημιουργηθούν ετικέτες από μια εργασία και πού εμφανίζονται &mdash; σε κάρτες, στο φίλτρο της πλαϊνής στήλης, στην αναζήτηση και στο ημερολόγιο/χρονοδιάγραμμα.',
        'tags_tip' => 'Μια ετικέτα είναι το σωστό σπίτι για ένα θέμα «κάποτε / ίσως». Επισημάνετε μια χούφτα ιδέες ως <em>Blue Sky</em> και μπορείτε να τις βρείτε οποιαδήποτε στιγμή με το φίλτρο ετικετών, χωρίς ξεχωριστή στήλη.',
        'settings_heading' => 'Ρυθμίσεις',
        'settings_intro' => 'Η σελίδα Ρυθμίσεων έχει μια καρτέλα για κάθε τομέα και βλέπετε τις καρτέλες που ο ρόλος σας επιτρέπει να αλλάξετε. Οι ρυθμίσεις ισχύουν για όλη την εγκατάσταση: μια αλλαγή εδώ διαμορφώνει τον πίνακα εργασιών, το ημερολόγιο και τις κάρτες για όλη την ομάδα, όχι μόνο για εσάς.',
        'settings_lookups_heading' => 'Καταστάσεις &amp; Προτεραιότητες',
        'settings_lookups_body' => 'Αυτές οι δύο καρτέλες διαχειρίζονται τις λίστες τιμών από τις οποίες αντλεί κάθε εργασία. Κάθε γραμμή έχει όνομα, χρώμα και σειρά εμφάνισης, και προσθέτετε, επεξεργάζεστε ή διαγράφετε γραμμές με τα κουμπιά στα δεξιά.',
        'settings_field_statuses' => '<strong>Καταστάσεις</strong> &mdash; οι καταστάσεις ροής εργασιών, που λειτουργούν και ως στήλες του πίνακα (εμφανίζονται με τη σειρά εμφάνισης). Μία κατάσταση είναι η <em>προεπιλογή</em> για τις νέες εργασίες. Μια κατάσταση που έχει επισημανθεί ως <em>Κλειστή</em> θεωρείται ολοκληρωμένη &mdash; οι εργασίες που μετακινούνται σε αυτήν καταγράφουν χρόνο ολοκλήρωσης και βγαίνουν από τους μετρητές ανοιχτών εργασιών. Μια κατάσταση μπορεί επίσης να γίνει ανενεργή ώστε να αποσυρθεί χωρίς να χαθεί το ιστορικό.',
        'settings_field_priorities' => '<strong>Προτεραιότητες</strong> &mdash; οι ζώνες προτεραιότητας που εμφανίζονται ως έγχρωμη κουκκίδα σε κάθε κάρτα. Μία προτεραιότητα είναι η προεπιλογή για τις νέες εργασίες.',
        'settings_card_heading' => 'Κάρτα',
        'settings_card_body' => 'Η καρτέλα Κάρτα είναι ένα σύνολο πλαισίων ελέγχου που καθορίζουν ποιες επιπλέον λεπτομέρειες εμφανίζονται σε κάθε κάρτα πίνακα και λίστας, ώστε να σαρώνετε τις εργασίες χωρίς να τις ανοίγετε: κουκκίδα προτεραιότητας, αρχικά του ανατεθειμένου, ομάδα, ημερομηνία έναρξης, προθεσμία, απόσπασμα περιγραφής, πρόοδος υποεργασιών και ένδειξη συσχετισμένων στοιχείων. Ο τίτλος της εργασίας εμφανίζεται πάντα. Οι αλλαγές ισχύουν την επόμενη φορά που θα φορτωθεί ο πίνακας εργασιών.',
        'settings_calendar_heading' => 'Επιλογές ημερολογίου',
        'settings_calendar_body' => 'Η καρτέλα Ημερολόγιο έχει μία μόνο απόφαση: πώς σχεδιάζεται στο ημερολόγιο Εργασιών μια <strong>πολυήμερη εργασία</strong> &mdash; μια εργασία της οποίας η ημερομηνία έναρξης είναι νωρίτερα από την προθεσμία. Επιλέξτε έναν από τρεις τρόπους:',
        'settings_calendar_deadline' => '<strong>Ένδειξη προθεσμίας</strong> (η προεπιλογή) &mdash; η εργασία εμφανίζεται μία φορά, ως μία ένδειξη στην ημερομηνία προθεσμίας της. Έτσι το ημερολόγιο επικεντρώνεται σε ό,τι πρέπει να ολοκληρωθεί και όχι στις διάρκειες, και είναι η πιο τακτοποιημένη επιλογή όταν έχετε πολλές εργασίες. Ολόκληρο το διάστημα φαίνεται ακόμη στο Χρονοδιάγραμμα.',
        'settings_calendar_span' => '<strong>Εκτεινόμενη μπάρα</strong> &mdash; η εργασία σχεδιάζεται ως μία συνεχής μπάρα από την ημερομηνία έναρξης έως την προθεσμία, που συνεχίζεται στην επόμενη γραμμή στο τέλος κάθε εβδομάδας. Οι μπάρες στοιβάζονται σε λωρίδες ώστε να μην επικαλύπτονται. Ιδανικό όταν έχει μεγαλύτερη σημασία να βλέπετε πόσο διαρκούν τα πράγματα και τι επικαλύπτεται παρά ένα τακτοποιημένο πλέγμα.',
        'settings_calendar_everyday' => '<strong>Κάθε ημέρα</strong> &mdash; μια ένδειξη επαναλαμβάνεται σε κάθε κελί ημέρας που καλύπτει η εργασία. Το πιο πλήρες &mdash; η εργασία είναι αδύνατο να χαθεί σε οποιαδήποτε ημέρα &mdash; αλλά λίγες μεγάλες εργασίες μπορούν να γεμίσουν γρήγορα το πλέγμα.',
        'settings_calendar_note' => 'Όποιον τρόπο κι αν επιλέξετε, μια εργασία που έχει <em>μόνο</em> προθεσμία (χωρίς ημερομηνία έναρξης) εμφανίζεται πάντα ως μία ένδειξη σε εκείνη την ημερομηνία &mdash; οι τρόποι αλλάζουν μόνο το πώς σχεδιάζεται ένα πραγματικό <em>εύρος</em> ημερομηνιών. Το ίδιο το ημερολόγιο δείχνει τον τρέχοντα τρόπο στη γραμμή εργαλείων του, με έναν σύνδεσμο <strong>Αλλαγή</strong> που οδηγεί κατευθείαν πίσω σε αυτήν την καρτέλα.',
        'settings_checklists_heading' => 'Λίστες ελέγχου',
        'settings_checklists_body' => 'Ενεργοποιήστε το <strong>Να επιτρέπονται λίστες ελέγχου στις εργασίες</strong> και κάθε εργασία και υποεργασία αποκτά μια ενότητα <strong>Λίστα ελέγχου</strong>: επισυνάψτε οποιαδήποτε λίστα ελέγχου από την ενότητα Λίστες ελέγχου που έχει οριστεί να ισχύει για <em>Εργασίες</em> ή <em>Και τα δύο</em>, και μετά σημειώστε τα βήματά της καθώς προχωράτε. Ένα βήμα που ζητά τιμή δεν μπορεί να σημειωθεί χωρίς αυτήν. Είναι απενεργοποιημένο από προεπιλογή. Μια εργασία μπορεί να έχει περισσότερες από μία λίστες ελέγχου. Σύρετε μια λίστα ελέγχου, ή ένα βήμα μέσα σε αυτήν, από τη λαβή <strong>&#8942;&#8942;</strong> για να αλλάξετε τη σειρά.',
        'settings_checklists_standard' => '<strong>Τυπική</strong> λίστα ελέγχου &mdash; μπορείτε και πάλι να ολοκληρώσετε την εργασία με εκκρεμή υποχρεωτικά βήματα. Σας ρωτά πρώτα και το ιστορικό της εργασίας καταγράφει ποιος την ολοκλήρωσε και ποια βήματα παραλείφθηκαν.',
        'settings_checklists_critical' => '<strong>Κρίσιμη</strong> λίστα ελέγχου (λουκέτο) &mdash; η εργασία δεν μπορεί να ολοκληρωθεί μέχρι να γίνουν τα υποχρεωτικά βήματά της, είτε από το πλαίσιο κατάστασης, είτε σύροντας την κάρτα σε κλειστή στήλη, είτε σημειώνοντας μια υποεργασία, είτε μέσω του API.',
        'settings_evidence_heading' => 'Τεκμήρια',
        'settings_evidence_body' => 'Τέσσερις επιλογές για το αρχείο που διαβάζει ένας ελεγκτής. Καθεμία έχει ως προεπιλογή την επιεική, και όποια κι αν διαλέξετε, τίποτα από όσα έχουν ήδη καταγραφεί δεν χάνεται.',
        'settings_evidence_checklist' => '<strong>Αλλαγή της λίστας ελέγχου μιας ολοκληρωμένης εργασίας</strong> - <em>επιτρέπεται και καταγράφεται</em> (ένα τυπογραφικό λάθος μπορεί να διορθωθεί, η αλλαγή επισημαίνεται στην αναφορά) ή <em>απορρίπτεται μέχρι να ανοίξει ξανά η εργασία</em>.',
        'settings_evidence_delete' => '<strong>Διαγραφή μιας εμφάνισης επανάληψης</strong> - <em>επιτρέπεται και διατηρείται ως Αφαιρέθηκε</em> (ένα παγωμένο αντίγραφό της μένει στην αναφορά) ή <em>δεν επιτρέπεται - παραλείψτε την αντί γι\' αυτό</em>.',
        'settings_evidence_skip' => '<strong>Κατάσταση στην οποία μετακινείται μια εμφάνιση που παραλείφθηκε</strong> - μία από τις κλειστές καταστάσεις σας. Από προεπιλογή η τελευταία στη σειρά σας, που σε μια τυπική εγκατάσταση είναι η <em>Ακυρώθηκε</em>.',
        'settings_evidence_access' => '<strong>Ποιος μπορεί να εκτελέσει την αναφορά τεκμηρίων</strong> - οποιοσδήποτε μπορεί να δει την επαναλαμβανόμενη εργασία ή μόνο οι ρόλοι που έχουν το <em>Εκτέλεση της αναφοράς τεκμηρίων</em>.',
        'settings_checklists_note' => 'Η ρύθμιση εταιρείας <strong>Αποκλεισμός όλων</strong> στις Αιτήματα &rarr; Ρυθμίσεις &rarr; Λίστες ελέγχου ισχύει και για τις εργασίες. Μια επαναλαμβανόμενη εργασία δίνει σε κάθε νέα εμφάνιση ένα φρέσκο αντίγραφο των λιστών ελέγχου της, χωρίς σημειώσεις. Η απενεργοποίηση αυτής της ρύθμισης κρύβει την ενότητα και σταματά την επιβολή της, και δεν διαγράφει ποτέ μια λίστα ελέγχου.',
        'settings_tags_heading' => 'Επιλογές ετικετών',
        'settings_tags_body' => 'Η καρτέλα Ετικέτες κάνει δύο δουλειές. Το επάνω μισό είναι η <strong>λίστα ετικετών</strong> &mdash; προσθέστε, επεξεργαστείτε, διαγράψτε και αλλάξτε χρώμα στις ετικέτες που μπορεί να εφαρμόσει η ομάδα σας (καθεμία είναι απλώς ένα όνομα και ένα χρώμα). Το κάτω μισό, οι <strong>Επιλογές εμφάνισης</strong>, είναι πέντε διακόπτες που καθορίζουν πώς λειτουργεί η προσθήκη ετικετών και πού εμφανίζονται:',
        'settings_tags_allow' => '<strong>Να επιτρέπονται νέες ετικέτες από μια εργασία</strong> (απενεργοποιημένο από προεπιλογή) &mdash; ο διακόπτης διαχειριζόμενο έναντι ανοιχτού. Απενεργοποιημένο, η λίστα ετικετών είναι σταθερό λεξιλόγιο: οι τεχνικοί μπορούν να επιλέξουν μόνο υπάρχουσες ετικέτες και οι νέες προστίθενται εδώ στις Ρυθμίσεις &mdash; ιδανικό για ένα ελεγχόμενο σύνολο όπως Ασφάλεια ή ISO. Ενεργοποιημένο, ο επιλογέας ετικετών σε μια εργασία επιτρέπει επίσης σε έναν τεχνικό να πληκτρολογήσει και να δημιουργήσει επιτόπου μια νέα ετικέτα.',
        'settings_tags_chips' => '<strong>Ετικέτες στις κάρτες</strong> &mdash; εμφάνιση έγχρωμων ετικετών στις κάρτες του πίνακα και της λίστας. Απενεργοποιήστε το αν προτιμάτε ελάχιστες κάρτες.',
        'settings_tags_filter' => '<strong>Φίλτρο πλαϊνής στήλης</strong> &mdash; εμφάνιση αναπτυσσόμενης λίστας Ετικέτας στην πλαϊνή στήλη του πίνακα/της λίστας, ώστε να περιορίσετε την προβολή σε μία ετικέτα.',
        'settings_tags_search' => '<strong>Αντιστοίχιση στην αναζήτηση</strong> &mdash; συμπερίληψη των ονομάτων ετικετών σε ό,τι ταιριάζει το πλαίσιο αναζήτησης, ώστε η πληκτρολόγηση ενός ονόματος ετικέτας να βρίσκει κάθε εργασία που την φέρει.',
        'settings_tags_calendar' => '<strong>Ημερολόγιο &amp; χρονοδιάγραμμα</strong> &mdash; εμφάνιση μικρών κουκκίδων ετικετών στις μπάρες εργασιών στις προβολές ημερολογίου και χρονοδιαγράμματος. Απενεργοποιημένο από προεπιλογή, αφού αυτές οι προβολές εστιάζουν στις ημερομηνίες.',
        'settings_tags_note' => 'Οι διακόπτες είναι ανεξάρτητοι &mdash; μπορείτε, για παράδειγμα, να κρατήσετε τις ετικέτες εκτός των καρτών αλλά να φιλτράρετε και να αναζητάτε με αυτές. Οι αλλαγές εμφάνισης ετικετών ισχύουν την επόμενη φορά που θα φορτωθεί μια προβολή.',
        'tips_heading' => 'Γρήγορες συμβουλές',
        'tips_intro' => 'Μερικές συντομεύσεις και συνήθειες που κάνουν την ενότητα πιο γρήγορη στη χρήση.',
        'tip1' => '<strong>Το δεξί κλικ είναι πιο γρήγορο.</strong> Αναθέστε ξανά ή αλλάξτε προτεραιότητα σε μια κάρτα από το μενού περιβάλλοντός της χωρίς να την ανοίξετε.',
        'tip2' => '<strong>Νέα ή γρήγορη προσθήκη.</strong> Το <strong>Νέα</strong> επάνω δεξιά σε κάθε προβολή Εργασιών ζητά έναν τίτλο και ανοίγει την εργασία. Στον πίνακα εργασιών, το + σε μια στήλη κάνει το ίδιο στην κατάσταση εκείνης της στήλης - πληκτρολογήστε έναν τίτλο, πατήστε Enter και συμπληρώστε τα υπόλοιπα αργότερα.',
        'tip3' => '<strong>Η αναζήτηση είναι άμεση.</strong> Φιλτράρει καθώς πληκτρολογείτε και ταιριάζει με κάθε λέξη &mdash; δεν χρειάζεται να περιμένετε ή να πατήσετε Enter.',
        'tip4' => '<strong>Ετικέτες για θέματα.</strong> Χρησιμοποιήστε ετικέτες για ό,τι διασχίζει τις καταστάσεις &mdash; συμμόρφωση, ασφάλεια, έργα.',
        'tip5' => '<strong>Δύο ημερομηνίες, δύο προβολές.</strong> Ορίστε ημερομηνία έναρξης και προθεσμία και η εργασία σχεδιάζεται μόνη της τόσο στο ημερολόγιο όσο και στο χρονοδιάγραμμα.',
        'tip6' => '<strong>Συσχετίστε την πηγή.</strong> Επισυνάψτε το αίτημα ή την αλλαγή από την οποία προήλθε μια εργασία, ώστε το πλαίσιο να είναι ένα κλικ μακριά.',
        'tip7' => '<strong>Σύρετε τη γραμμή.</strong> Στο χρονοδιάγραμμα, σύρετε το σώμα της γραμμής για να αλλάξετε χρονοπρογραμματισμό και σύρετε οποιαδήποτε άκρη για να ορίσετε απευθείας την ημερομηνία έναρξης ή την προθεσμία &mdash; χωρίς να χρειάζεται πάνελ.',
        'tip8' => '<strong>Φτιάξτε τον δικό σας πίνακα.</strong> Στην προβολή Πίνακα, επιλέξτε ποιες στήλες θα εμφανίζονται, σύρετέ τες στη σειρά που θέλετε, ταξινομήστε και φιλτράρετε &mdash; η διάταξή σας αποθηκεύεται για κάθε τεχνικό ξεχωριστά.',
    ],
